// ─── Auth Modal ───────────────────────────────────────────────────────────────

type AuthStep = "email" | "otp" | "success";

function AuthModal({ open, onOpenChange, onSuccess }: { open: boolean; onOpenChange: (v: boolean) => void; onSuccess: () => void }) {
  const { sendOtp, verifyOtp, signInGuest } = useAuth();
  const [step, setStep] = useState<AuthStep>("email");
  const [email, setEmail] = useState("");
  const [otp, setOtp] = useState("");
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const resetModal = useCallback(() => {
    setStep("email");
    setEmail("");
    setOtp("");
    setCode("");
    setLoading(false);
    setError("");
  }, []);

  const handleOpenChange = useCallback(
    (v: boolean) => {
      if (!v) resetModal();
      onOpenChange(v);
    },
    [onOpenChange, resetModal]
  );

  const handleSendOtp = async () => {
    if (!email.trim()) {
      setError("Please enter your email address.");
      return;
    }
    setLoading(true);
    setError("");
    const result = await sendOtp(email.trim());
    setLoading(false);
    if (!result.success) {
      setError(result.error || "Failed to send code.");
      return;
    }
    if (result.code) setCode(result.code);
    setStep("otp");
  };

  const handleVerifyOtp = async () => {
    if (otp.length !== 6) {
      setError("Please enter the full 6-digit code.");
      return;
    }
    setLoading(true);
    setError("");
    const result = await verifyOtp(email.trim(), otp);
    setLoading(false);
    if (!result.success) {
      setError(result.error || "Verification failed.");
      setOtp("");
      return;
    }
    toast.success("Welcome to Nexus Academy!");
    setStep("success");
    setTimeout(() => {
      onSuccess();
      resetModal();
    }, 600);
  };

  const handleGuest = async () => {
    setLoading(true);
    setError("");
    const result = await signInGuest();
    setLoading(false);
    if (!result.success) {
      setError(result.error || "Failed to sign in as guest.");
      return;
    }
    toast.success("Welcome, Guest!");
    setStep("success");
    setTimeout(() => {
      onSuccess();
      resetModal();
    }, 600);
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent
        showCloseButton={false}
        className="max-w-4xl p-0 overflow-hidden border-border/50 rounded-2xl"
      >
        <div className="relative flex flex-col md:flex-row min-h-[520px]">
          {/* Aurora orbs background */}
          <div className="absolute inset-0 overflow-hidden -z-10">
            <div className="absolute -top-24 -left-24 h-72 w-72 rounded-full bg-purple-500/20 blur-3xl" />
            <div className="absolute -bottom-24 -right-24 h-72 w-72 rounded-full bg-rose-500/20 blur-3xl" />
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 h-64 w-64 rounded-full bg-emerald-500/10 blur-3xl" />
          </div>

          {/* Left panel – branding (hidden on mobile) */}
          <div className="hidden md:flex flex-col justify-between w-5/12 p-8 bg-muted/50 rounded-l-2xl border-r border-border/50">
            <div>
              <div className="flex items-center gap-2 mb-8">
                <img src="/logo.svg" alt="Logo" className="h-8 w-8" />
                <span className="text-lg font-bold">Nexus Academy</span>
              </div>
              <h3 className="text-xl font-semibold mb-4">
                Your AI-Powered Academic Command Center
              </h3>
              <ul className="space-y-3 text-sm text-muted-foreground">
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
                  AI Tutor for personalized learning
                </li>
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
                  Adaptive quizzes &amp; flashcards
                </li>
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
                  Focus timer &amp; study planner
                </li>
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
                  Track achievements &amp; milestones
                </li>
              </ul>
            </div>
            <p className="text-xs text-muted-foreground">
              &copy; {new Date().getFullYear()} Nexus Academy. All rights reserved.
            </p>
          </div>

          {/* Right panel – auth form */}
          <div className="flex-1 flex flex-col justify-center p-8 relative">
            {/* Mobile logo */}
            <div className="flex md:hidden items-center gap-2 mb-6">
              <img src="/logo.svg" alt="Logo" className="h-7 w-7" />
              <span className="font-bold">Nexus Academy</span>
            </div>

            <AnimatePresence mode="wait">
              {step === "email" && (
                <motion.div
                  key="email"
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  transition={{ duration: 0.2 }}
                >
                  <DialogHeader>
                    <DialogTitle className="text-2xl">Sign in</DialogTitle>
                    <DialogDescription>
                      Enter your email to receive a one-time verification code.
                    </DialogDescription>
                  </DialogHeader>
                  <div className="mt-6 space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="auth-email">Email</Label>
                      <Input
                        id="auth-email"
                        type="email"
                        placeholder="you@example.com"
                        value={email}
                        onChange={(e) => {
                          setEmail(e.target.value);
                          setError("");
                        }}
                        onKeyDown={(e) => e.key === "Enter" && handleSendOtp()}
                        disabled={loading}
                        autoFocus
                      />
                    </div>
                    {error && (
                      <p className="text-sm text-destructive">{error}</p>
                    )}
                    <Button
                      className="w-full"
                      onClick={handleSendOtp}
                      disabled={loading}
                    >
                      {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                      Send Code
                    </Button>
                  </div>
                </motion.div>
              )}

              {step === "otp" && (
                <motion.div
                  key="otp"
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  transition={{ duration: 0.2 }}
                >
                  <DialogHeader>
                    <DialogTitle className="text-2xl">Verify code</DialogTitle>
                    <DialogDescription>
                      We sent a 6-digit code to <span className="font-medium text-foreground">{email}</span>
                    </DialogDescription>
                  </DialogHeader>
                  <div className="mt-6 space-y-4">
                    <div className="flex items-center justify-center gap-2 py-2">
                      <span className="text-xs text-muted-foreground">Your verification code:</span>
                      <Badge variant="outline" className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 font-mono text-sm px-3 py-1">
                        {code}
                      </Badge>
                    </div>
                    <div className="space-y-2">
                      <Label>Code</Label>
                      <InputOTP
                        maxLength={6}
                        value={otp}
                        onChange={(value) => {
                          setOtp(value);
                          setError("");
                        }}
                      >
                        <InputOTPGroup>
                          <InputOTPSlot index={0} />
                          <InputOTPSlot index={1} />
                          <InputOTPSlot index={2} />
                          <InputOTPSlot index={3} />
                          <InputOTPSlot index={4} />
                          <InputOTPSlot index={5} />
                        </InputOTPGroup>
                      </InputOTP>
                    </div>
                    {error && (
                      <p className="text-sm text-destructive">{error}</p>
                    )}
                    <Button
                      className="w-full"
                      onClick={handleVerifyOtp}
                      disabled={loading || otp.length !== 6}
                    >
                      {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                      Verify
                    </Button>
                    <button
                      type="button"
                      className="w-full text-sm text-muted-foreground hover:text-foreground transition-colors text-center"
                      onClick={() => {
                        setStep("email");
                        setOtp("");
                        setCode("");
                        setError("");
                      }}
                    >
                      Back to email
                    </button>
                  </div>
                </motion.div>
              )}

              {step === "success" && (
                <motion.div
                  key="success"
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  transition={{ duration: 0.2 }}
                  className="flex flex-col items-center justify-center py-8 text-center"
                >
                  <motion.div
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    transition={{ type: "spring", stiffness: 200, damping: 15, delay: 0.1 }}
                  >
                    <CheckCircle2 className="h-16 w-16 text-emerald-500 mb-4" />
                  </motion.div>
                  <h3 className="text-xl font-semibold">Welcome!</h3>
                  <p className="text-muted-foreground mt-2">
                    Redirecting to your dashboard…
                  </p>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Guest sign-in always visible at bottom */}
            {step !== "success" && (
              <div className="mt-auto pt-6">
                <div className="relative">
                  <div className="absolute inset-0 flex items-center">
                    <span className="w-full border-t border-border" />
                  </div>
                  <div className="relative flex justify-center text-xs uppercase">
                    <span className="bg-background px-2 text-muted-foreground">
                      or
                    </span>
                  </div>
                </div>
                <Button
                  variant="ghost"
                  className="w-full mt-4"
                  onClick={handleGuest}
                  disabled={loading}
                >
                  {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  Continue as Guest
                </Button>
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

