"use client";

import { useCallback, useEffect, useState } from "react";

export interface AuthUser {
  id: string;
  email: string | null;
  name: string | null;
  isGuest: boolean;
  stream?: string | null;
  createdAt?: string;
}

interface AuthState {
  user: AuthUser | null;
  isAuthenticated: boolean;
  isLoading: boolean;
}

export function useAuth() {
  const [state, setState] = useState<AuthState>({
    user: null,
    isAuthenticated: false,
    isLoading: true,
  });

  // Check session on mount
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch("/api/auth/session");
        const data = await res.json();
        if (cancelled) return;
        if (data.authenticated && data.user) {
          setState({
            user: data.user,
            isAuthenticated: true,
            isLoading: false,
          });
        } else {
          setState({ user: null, isAuthenticated: false, isLoading: false });
        }
      } catch {
        if (!cancelled) {
          setState({ user: null, isAuthenticated: false, isLoading: false });
        }
      }
    })();
    return () => { cancelled = true; };
  }, []);

  const signInEmail = useCallback(async (email: string): Promise<boolean> => {
    try {
      const res = await fetch("/api/auth/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, code: "" }),
      });
      // This won't actually work - the real flow is: send-otp first, then verify-otp with code
      return false;
    } catch {
      return false;
    }
  }, []);

  const sendOtp = useCallback(async (email: string): Promise<{ success: boolean; code?: string; error?: string }> => {
    try {
      const res = await fetch("/api/auth/send-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });
      const data = await res.json();
      if (!res.ok) return { success: false, error: data.error || "Failed to send code." };
      return { success: true, code: data.code };
    } catch {
      return { success: false, error: "Network error. Please try again." };
    }
  }, []);

  const verifyOtp = useCallback(async (email: string, code: string): Promise<{ success: boolean; user?: AuthUser; error?: string }> => {
    try {
      const res = await fetch("/api/auth/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, code }),
      });
      const data = await res.json();
      if (!res.ok) return { success: false, error: data.error || "Verification failed." };
      const user: AuthUser = {
        id: data.user.id,
        email: data.user.email,
        name: data.user.name,
        isGuest: data.user.isGuest,
      };
      setState({ user, isAuthenticated: true, isLoading: false });
      return { success: true, user };
    } catch {
      return { success: false, error: "Network error. Please try again." };
    }
  }, []);

  const signInGuest = useCallback(async (): Promise<{ success: boolean; user?: AuthUser; error?: string }> => {
    try {
      const res = await fetch("/api/auth/guest", { method: "POST" });
      const data = await res.json();
      if (!res.ok) return { success: false, error: data.error || "Failed to sign in as guest." };
      const user: AuthUser = {
        id: data.user.id,
        email: data.user.email,
        name: data.user.name,
        isGuest: data.user.isGuest,
      };
      setState({ user, isAuthenticated: true, isLoading: false });
      return { success: true, user };
    } catch {
      return { success: false, error: "Network error. Please try again." };
    }
  }, []);

  const signOut = useCallback(async () => {
    try {
      await fetch("/api/auth/signout", { method: "POST" });
    } catch {
      // ignore
    }
    setState({ user: null, isAuthenticated: false, isLoading: false });
  }, []);

  return { ...state, sendOtp, verifyOtp, signInGuest, signOut };
}
